import { useEffect } from "react";
import { useState } from "react";
import Card from "./card";
import { useRouter, usePathname, useSearchParams } from "next/navigation";

export default function CardList() {

    const [experiences, setExperiences] = useState<ExperienceType[]>([])

    useEffect(() => {
    // Fetch experiences from the API
    fetch("/api/experience")
        .then((response) => response.json())
        .then((data) => {
        setExperiences(data);
        })
        .catch((error) => console.error("Error fetching experiences:", error));
    }, []);

    return (
        <div className="flex justify-center items-start h-[85%] w-[70%] rounded-[3vw] gap-8 overflow-y-scroll bubble p-[3vw]">
            <div className="flex items-center justify-center gap-8">
                <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-8 flex-grow">
                    {experiences.map((experience) => (
                    <Card key={experience._id} experience={experience} />
                    ))}
                </div>
            </div>
        </div>
    );
}

